type IconProps = { size?: number; className?: string }

function Glyph({ d, size = 16, className }: IconProps & { d: string }) {
  return (
    <svg className={className} width={size} height={size} viewBox="0 0 24 24" fill="currentColor" aria-hidden>
      <path d={d} />
    </svg>
  )
}

